<?php require_once dirname(__DIR__).'/includes/auth.php';require_admin();$quizzes=db()->query("SELECT q.*,u.name creator,(SELECT COUNT(*) FROM questions WHERE quiz_id=q.id) questions,(SELECT COUNT(*) FROM attempts WHERE quiz_id=q.id AND submitted_at IS NOT NULL) responses FROM quizzes q JOIN users u ON u.id=q.created_by ORDER BY q.created_at DESC")->fetchAll();$stats=db()->query("SELECT (SELECT COUNT(*) FROM quizzes) quizzes,(SELECT COUNT(*) FROM attempts WHERE submitted_at IS NOT NULL) responses,(SELECT COUNT(*) FROM users) users")->fetch();$pageTitle='Administração · QMAX Quiz';require dirname(__DIR__).'/includes/header.php'; ?>
